    for (int i = 0; i < q; i++) { cin >> ql[i] >> qr[i]; ql[i]--; qr[i]--; order[i] = i; }
    int block = max(1, n / max(1, (int)sqrt((double)q)));
    sort(order.begin(), order.end(), [&](int a, int b) {
