import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;
    static InputStream in = System.in;

    static int read() throws IOException {
        if (ptr == len) { len = in.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != '-' && (c < '0' || c > '9')) c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + c - '0'; c = read(); }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException { return (int) nextLong(); }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), q = nextInt();
        int[] tags = new int[n];
        for (int i = 0; i < n; i++) tags[i] = nextInt();
        // compress labels so frequencies fit in an array
        int[] vals = tags.clone();
        Arrays.sort(vals);
        int k = 0;
        for (int i = 0; i < n; i++) if (i == 0 || vals[i] != vals[i - 1]) vals[k++] = vals[i];
        for (int i = 0; i < n; i++) tags[i] = Arrays.binarySearch(vals, 0, k, tags[i]);
        int[] ql = new int[q], qr = new int[q];
        for (int i = 0; i < q; i++) { ql[i] = nextInt() - 1; qr[i] = nextInt() - 1; }
        int block = Math.max(1, n / Math.max(1, (int) Math.sqrt(q)));
        // sort by a packed key: block, then right end (reversed in odd blocks), then index
        long[] keys = new long[q];
        for (int i = 0; i < q; i++) {
            long b = ql[i] / block;
            long r = (b & 1) == 1 ? (n - qr[i]) : qr[i];
            keys[i] = (b << 40) | (r << 20) | i;
        }
        Arrays.sort(keys);
        int[] freq = new int[k];
        long[] ans = new long[q];
        long groups = 0;
        int left = 0, right = -1;
        for (long key : keys) {
            int qi = (int) (key & ((1 << 20) - 1));
            int L = ql[qi], R = qr[qi];
            while (left > L) { int v = tags[--left]; groups += freq[v] & 1; freq[v]++; }
            while (right < R) { int v = tags[++right]; groups += freq[v] & 1; freq[v]++; }
            while (left < L) { int v = tags[left++]; freq[v]--; groups -= freq[v] & 1; }
            while (right > R) { int v = tags[right--]; freq[v]--; groups -= freq[v] & 1; }
            ans[qi] = groups;
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < q; i++) { if (i > 0) sb.append(' '); sb.append(ans[i]); }
        System.out.println(sb);
    }
}

package main

import (
	"bufio"
	"math"
	"os"
	"sort"
	"strconv"
)

var rd = bufio.NewReaderSize(os.Stdin, 1<<20)

func readInt() int {
	n := 0
	c, _ := rd.ReadByte()
	for c == ' ' || c == '\n' || c == '\r' {
		c, _ = rd.ReadByte()
	}
	neg := c == '-'
	if neg {
		c, _ = rd.ReadByte()
	}
	for c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, _ = rd.ReadByte()
	}
	if neg {
		return -n
	}
	return n
}

func main() {
	n, q := readInt(), readInt()
	tags := make([]int, n)
	for i := range tags {
		tags[i] = readInt()
	}
	// compress labels so frequencies fit in a slice
	vals := append([]int(nil), tags...)
	sort.Ints(vals)
	k := 0
	for i, v := range vals {
		if i == 0 || v != vals[i-1] {
			vals[k] = v
			k++
		}
	}
	vals = vals[:k]
	for i, v := range tags {
		tags[i] = sort.SearchInts(vals, v)
	}
	ql := make([]int, q)
	qr := make([]int, q)
	order := make([]int, q)
	for i := 0; i < q; i++ {
		ql[i] = readInt() - 1
		qr[i] = readInt() - 1
		order[i] = i
	}
	block := max(1, n/max(1, int(math.Sqrt(float64(q)))))
	sort.Slice(order, func(x, y int) bool {
		a, b := order[x], order[y]
		ba, bb := ql[a]/block, ql[b]/block
		if ba != bb {
			return ba < bb
		}
		if ba&1 == 1 {
			return qr[a] > qr[b]
		}
		return qr[a] < qr[b]
	})
	freq := make([]int, k)
	ans := make([]int, q)
	groups := 0
	left, right := 0, -1
	for _, qi := range order {
		L, R := ql[qi], qr[qi]
		for left > L {
			left--
			v := tags[left]
			groups += freq[v] & 1
			freq[v]++
		}
		for right < R {
			right++
			v := tags[right]
			groups += freq[v] & 1
			freq[v]++
		}
		for left < L {
			v := tags[left]
			left++
			freq[v]--
			groups -= freq[v] & 1
		}
		for right > R {
			v := tags[right]
			right--
			freq[v]--
			groups -= freq[v] & 1
		}
		ans[qi] = groups
	}
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	for i, a := range ans {
		if i > 0 {
			w.WriteByte(' ')
		}
		w.WriteString(strconv.Itoa(a))
	}
	w.WriteByte('\n')
}
